# Find first names of students who have cat or dog pets
students_with_cats_or_dogs = students.WHERE(
    HAS(has_pets.WHERE(
        (pet.pettype == "cat") | (pet.pettype == "dog")
    )) == 1
).CALCULATE(fname=fname)

# Calculate the average score of all shops at the graph level
below_average_shops = coffee_shop.CALCULATE(
    avg_score=AVG(shops.score)
).shops.WHERE(
    score < avg_score
).CALCULATE(
    shop_id=shop_id,
    address=address
)

female_students_by_major = students.WHERE(
    sex == 'F'
).PARTITION(
    name="majors",
    by=major
).CALCULATE(
    major=major,
    num_female_students=COUNT(students)
).TOP_K(1, by=num_female_students.DESC()).CALCULATE(
    major=major,
    num_female_students=num_female_students
)

# Find dorms with TV Lounge but no Study Room
dorms_with_tv_no_study = dorms.WHERE(
    HAS(has_amenities.WHERE(dorm_amenity.amenity_name == "TV Lounge")) == 1
).WHERE(
    HASNOT(has_amenities.WHERE(dorm_amenity.amenity_name == "Study Room")) == 1
).CALCULATE(dorm_name=dorm_name)

# Find students who have taken prerequisite courses for "International Finance"
students_with_prereqs = courses.WHERE(
    title == "International Finance"
).prereqs.course.sections.take.student.CALCULATE(
    student_name=name
)

lowest_rated_item = items.WHERE(
    HAS(reviews) == 1
).CALCULATE(
    item_title=title,
    avg_rating=AVG(reviews.rating)
).TOP_K(1, by=avg_rating.ASC()).CALCULATE(
    item_title=item_title
)

# Calculate the average claimed amount across all claims and filter
result = insurance_policies.CALCULATE(
    avg_claimed_amount = AVG(claim.amount_claimed)
).claim.WHERE(
    amount_claimed > avg_claimed_amount
).CALCULATE(
    claim_date = date_claim_made,
    settlement_date = date_claim_settled
)

